const source=String.raw`
const word=/^\\[A-Za-z]+$/;
const names=['alpha','beta','gamma','delta','varepsilon','eta','theta','lambda','mu','xi','pi','rho','sigma','varphi','psi','infty'];
const funcs=['sin','cos','tan','cot','sec','arcsin','arccos','arctan','ln','log','exp'];
const terminals=new Set(names.map(x=>'\\'+x));
const fn=new Set(funcs.map(x=>'\\'+x));
const tokenPattern=/\\[A-Za-z]+|\\[^A-Za-z]|\d+(?:\.\d+)?|[ \t]+|./gu;
function convert(input){
  let line=input;
  for(let pass=0;pass<40;pass++){
    const tk=[...line.matchAll(tokenPattern)].filter(x=>!/^\s+$/.test(x[0]));
    const t=tk.map(x=>x[0]); 
    function group(i){
      const pairs={'{':'}','(':')','[':']','|':'|'};
      const close=pairs[t[i]];
      if(!close)return null;
      for(let k=i+1;k<t.length;k++){
        if(t[k]===close)return k+1;
        if(t[k]==='/'||['$','\\(','\\)','\\[','\\]','\\left','\\right','&'].includes(t[k]))return null;
        if(pairs[t[k]]){
          const end=group(k);
          if(end===null)return null;
          k=end-1;
        }
      }
      return null;
    }
    function script(i){return t[i]==='{'?group(i):(t[i]&&t[i]!=='/'?i+1:null);}
    function atom(i){
      if(i>=t.length)return null;
      let s=t[i], end;
      if(['(', '[', '|', '{'].includes(s)){end=group(i);if(end===null)return null;}
      else if(s==='\\frac'||s==='\\tfrac'||s==='\\dfrac'){
        end=script(i+1); if(end===null)return null;
        end=script(end); if(end===null)return null;
      }else if(s==='\\sqrt'||s==='\\mathrm'||s==='\\mathbb'){
        end=i+1;
        if(s==='\\sqrt'&&t[end]==='['){end=group(end);if(end===null)return null;}
        end=script(end);if(end===null)return null;
      }else if(fn.has(s)||terminals.has(s)||/^[A-Za-z0-9]/.test(s)){end=i+1;}
      else if(s==='\\,'&&t[i+1]==='\\mathrm'&&['d','{'].includes(t[i+2])){return i+1;}
      else return null;
      while(end<t.length){
        if(t[end]==="'"||t[end]==='!'){end++;continue;}
        if(t[end]!=='^'&&t[end]!=='_')break;
        const after=script(end+1);
        if(after===null)return null;
        end=after;
      }
      if(fn.has(s)){
        const arg=atom(end);
        if(arg===null)return null;
        end=arg;
      }
      return end;
    }
    let replacement=null;
    for(let at=0;at<t.length;at++){
      if(t[at]!=='/')continue;
      const right=atom(at+1);
      if(right===null)continue;
      let start=null;
      for(let j=at-1;j>=0;j--){
        if(t[j]==='/'||['$','\\(','\\)','\\[','\\]','&','=',',','，','。','；','\\text','\\ensuremath'].includes(t[j]))break;
        const prev=atom(j);
        if(prev===null||prev>at)continue;
        let end=prev;
        while(end<at){
          const next=atom(end);
          if(next===null||next>at)break;
          end=next;
        }
        if(end===at&&!["\\,","{","'"].includes(t[j]))start=j;
      }
      if(start===null)continue;
      const span=(from,to)=>line.slice(tk[from].index,tk[to-1].index+t[to-1].length);
      const operand=(from,to)=>{
        if(['(','['].includes(t[from])&&group(from)===to)return span(from+1,to-1);
        return span(from,to);
      };
      const numer=operand(start,at),denom=operand(at+1,right);
      if(!numer||!denom)continue;
      replacement=line.slice(0,tk[start].index)+'\\frac{'+numer+'}{'+denom+'}'+line.slice(tk[right-1].index+t[right-1].length);
      break;
    }
    if(replacement===null)return line;
    line=replacement;
  }
  throw new Error(input);
}
return convert;
`;store("converter",source);
