for (const k of ["sl1","nativeSl"]) {const src=load(k); const edits=src.filter(([,s])=>!s.startsWith("\\Theory")).map(([n,s])=>[n,s,convert(s)]);store("conv"+k,edits);text([k,edits.filter(([,s,t])=>s!==t).length,edits.filter(([,s,t])=>t.includes("/")).map(([n,s,t])=>n+":"+t).join("\n")]);}

