const results=await Promise.all(call.map(([i,name,start,end])=>tools.exec_command({cmd:`awk 'NR>=${start} && NR<=${end} {print}' 'output/${name}'`,max_output_tokens:35000})));
const combined=names.map(()=>[]);
for(let i=0;i<call.length;i++){const r=results[i];if(r.exit_code!==0||r.output.includes("truncated"))throw Error(JSON.stringify([call[i],r.original_token_count]));combined[call[i][0]].push(r.output);}
for(let i=0;i<names.length;i++){const full=combined[i].join("");store("tex"+i,full);text([names[i],full.length,full.split("\n").length-1]);}

