store("after2",full);
const names=load("names");
for(let i=0;i<names.length;i++){const old=load("tex"+i);const fresh=load("after"+i);const frac=s=>s.match(/\\(?:frac|tfrac|dfrac)\b/g)?.length??0;const slash=s=>s.split("\n").filter(l=>!l.startsWith("%")&&!l.startsWith("\\QuestionPage")).join("\n").match(/\//g)?.length??0;text({name:names[i],before:[slash(old),frac(old)],after:[slash(fresh),frac(fresh)]});if(slash(fresh))throw Error("remaining slash");}
const patchFn=String.raw`
function patch(names, prefix){
 const paths=names.map(n=>prefix+"output/"+n);
 const out=["*** Begin Patch"];
 for(let i=0;i<names.length;i++){
  const old=load("tex"+i).trimEnd().split("\n");
  const fresh=load("after"+i).trimEnd().split("\n");
  out.push("*** Update File: "+paths[i]);
  const insert=i<2?old.findIndex(l=>l==="\\usepackage{amsmath,amssymb,enumitem,tabularx}")+1:-1;
  const isChange=idx=>old[idx]!==fresh[idx+(insert>=0&&idx>=insert?1:0)];
  let changed=old.map((l,j)=>isChange(j)?j:null).filter(j=>j!==null);
  if(insert>=0)changed.push(insert);
  changed.sort((a,b)=>a-b);
  const intervals=[];
  for(const j of changed){
    if(intervals.length&&j-2<=intervals.at(-1)[1]) intervals.at(-1)[1]=Math.min(old.length,j+3);
    else intervals.push([Math.max(0,j-2),Math.min(old.length,j+3)]);
  }
  for(const [from,to] of intervals){
   out.push("@@");
   for(let j=from;j<to;j++){
    if(j===insert)out.push("+"+fresh[j]);
    if(isChange(j))out.push("-"+old[j],"+"+fresh[j+(insert>=0&&j>=insert?1:0)]);
    else out.push(" "+old[j]);
   }
  }
 }
 out.push("*** End Patch");
 return out.join("\n");
}
return patch;`;
store("patchFn",patchFn);
const patch=new Function("load",patchFn)(load)(names,"");text([patch.length,patch.split("\n").length]);const result=await tools.apply_patch(patch);text(result);

